import json
original_data = [
    {"prompt": "What is the primary objective of Regulation (EU) 2023/2854, also known as the Data Act?", "completion": "The primary objective of the Data Act is to lay down harmonised rules on fair access to and use of data. It aims to ensure that users of connected products or related services in the Union can access and use the data generated by those products/services and share that data with third parties."}, 
    {"prompt": "How does the Data Act define 'data'?", "completion": "Under the Data Act, 'data' is defined as any digital representation of acts, facts, or information and any compilation of such acts, facts, or information, including in the form of sound, visual, or audio-visual recording."}, 
    {"prompt": "What is a 'connected product' according to Article 2 of the Data Act?", "completion": "A 'connected product' is an item that obtains, generates, or collects data concerning its use or environment and that is able to communicate product data via an electronic communications service, physical connection, or on-device access."}, 
    {"prompt": "What obligation does Article 3 of the Data Act place on manufacturers regarding product data?", "completion": "Article 3 requires that connected products be designed and manufactured in such a manner that product data and related service data are, by default, easily, securely, and, where relevant and appropriate, directly accessible to the user."}, 
    {"prompt": "Under the Data Act, what information must be provided to a user before concluding a contract for a connected product?", "completion": "Before concluding a contract, the seller or manufacturer must provide clear information including: the type and volume of data likely to be generated, whether the product can generate data continuously in real-time, how the user may access that data, and the duration of data retention."}, 
    {"prompt": "Does the Data Act allow a data holder to use 'dark patterns' when users exercise their data rights?", "completion": "No. Article 4(4) specifies that data holders shall not make the exercise of choices or rights by the user unduly difficult, including by offering choices in a non-neutral manner or by subverting the user's autonomy through the structure or design of a user digital interface (commonly known as dark patterns)."}, 
    {"prompt": "What protection is provided for 'trade secrets' when data is accessed under the Data Act?", "completion": "Article 4(6) states that trade secrets shall be preserved and disclosed only if the data holder and the user take all necessary measures to preserve their confidentiality. The data holder can require the user to agree to technical and organizational measures to protect the trade secret's confidentiality."}, 
    {"prompt": "Can a 'gatekeeper' designated under the Digital Markets Act be a recipient of data requested by a user under the Data Act?", "completion": "No. Article 5(2) explicitly states that any undertaking designated as a gatekeeper under Regulation (EU) 2022/1925 (DMA) shall not be an eligible third party to receive data from a data holder at the request of a user."}, 
    {"prompt": "What are the rules regarding compensation for making data available in B2B relations under the Data Act?", "completion": "Article 9 stipulates that any compensation agreed between a data holder and a data recipient must be non-discriminatory and reasonable. For SMEs, the compensation shall not exceed the costs directly related to making the data available and the necessary technical interfaces."}, 
    {"prompt": "What is the purpose of 'Chapter V' of the Data Act regarding public sector bodies?", "completion": "Chapter V (Article 14) allows public sector bodies, the Commission, or the European Central Bank to request access to data from a data holder if they can demonstrate an 'exceptional need' to use that data, such as responding to a public emergency or fulfilling a task in the public interest mandated by law."} 
]

variations = []
for item in original_data:
    p = item["prompt"]
    c = item["completion"]
    
    # Var 1: Scenario based
    v1 = f"Imagine you are a legal compliance officer. {p}"
    
    # Var 2: Short/Chat style
    v2 = f"Hey, can you help me with this? {p}"
    
    # Var 3: Expert technical request
    v3 = f"Provide a technical summary of the following: {p}"
    
    variations.extend([{"prompt": v1, "completion": c}, {"prompt": v2, "completion": c}, {"prompt": v3, "completion": c}])

with open("data/pdf_synthetic_dataset.jsonl", "a") as f:
    for entry in variations:
        f.write(json.dumps(entry) + "\n")
